UPDATE public.image_backfill_queue q SET status = 'skipped', last_error = 'cleanup: target image no longer eligible (verified status changed, format changed, or attribute already set)', finished_at = now() WHERE q.status = 'pending' AND ((q.task = 'blurhash' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.blurhash IS NULL AND p.deleted_at IS NULL AND p.cf_sync_status = 'verified' AND p.format IN ('jpeg','png','webp'))) OR (q.task = 'content_hash' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.content_hash IS NULL AND p.deleted_at IS NULL AND p.cf_sync_status = 'verified')) OR (q.task = 'file_size' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.file_size_bytes IS NULL AND p.deleted_at IS NULL AND p.cf_sync_status = 'verified')) OR (q.task = 'reupload' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.cf_sync_status = 'orphaned' AND p.deleted_at IS NULL)));;
